import { getQueryParam, treeToFlatten } from '@/utils';
import { useEffect, useState } from 'react';
import { useHistory } from 'react-router-dom';
import CustomPage, { CustomPageStore } from '@/components/CustomPage';
import { Button, Tabs, Space, Spin, Message, Empty, Modal } from '@arco-design/web-react';
import classNames from 'classnames';
import styles from './index.module.less';
import ajax from '@/utils/ajax';
import Store from './store';
import { AsyncButton, MyErrorBoundary } from '@/components/custom';
import { useObserver } from 'mobx-react-lite';;
import { toJS } from 'mobx';
import { IconCalendar, IconCommon, IconCopy, IconDelete, IconToRight } from '@arco-design/web-react/icon';
import { MonacoCode } from '@/components/MonacoEditor';
import { moduleStore } from 'react-converter-code';


const { TabPane } = Tabs;

export default () => {

    const history = useHistory();
    const [id] = useState(() => {
        return getQueryParam(history.location.search, 'moduleId')
    })
    const [loading, setLoading] = useState<boolean>(false);
    const [store] = useState(() => new Store());

    useEffect(() => {
        if (!id) return;
        moduleStore.syncModuleIds([id]).then(() => {
            store.openModuleEidt(id)
        });
    }, [id])

    if (!id) {
        return <Empty />
    }

    return useObserver(() => {
        const { activeTab, setActiveTab } = store;

        const list = toJS(store.tabList);

        useEffect(() => {
            if (store.mode === "code") {
                const onKeyDown = (event) => {
                    // 检查按下的键是否是 "C" 和 "S" 键
                    if (event.key === 's' && (event.ctrlKey || event.metaKey)) {
                        // 用户按下 "s" 键和 ctrl 键
                        // 这里可以执行您想要的操作，比如触发购物车事件
                        event.preventDefault();
                        store.syncUpddatePageStore()
                        // 请将您的购物车逻辑放在这里
                    }
                }
                document.addEventListener('keydown', onKeyDown);
                return () => {
                    document.removeEventListener('keydown', onKeyDown);
                }
            }
        }, [store.mode])

        const { PageElement } = store
        return (
            <div className={`${styles.page}`}>
                {store.mode === "code" ? (
                    <MonacoCode
                        store={store.code}
                        extra={(
                            <Space key="0">
                                <Button type="primary" size="small" key="1"
                                    onClick={() => {
                                        // 转化为可视化布局
                                        store.openCavnasEditor();
                                    }}
                                >
                                    可视化
                                </Button>
                                <Button type="primary" size="small" key="3"
                                    onClick={() => {
                                        store.updatePageElement();
                                        !store.right && store.setRight(true);
                                    }}
                                >
                                    预览
                                </Button>
                                <AsyncButton key="save" size="small" type="primary"
                                    onClick={() => {
                                        return store.saveData();
                                    }}
                                >
                                    保存
                                </AsyncButton>
                                <Button type="primary" size="small" key="2"
                                    onClick={() => {
                                        store.syncUpddatePageStore()
                                    }}
                                >执行</Button>
                            </Space>
                        )}
                        right={
                            store.right ? (
                                <div>
                                    <Tabs type="card" extra={
                                        <Space>
                                            <Button
                                                onClick={() => {
                                                    store.setPVisible(true)
                                                    store.setRight(false)
                                                }} 
                                                size='small' type='primary' icon={<IconCopy />}
                                            />
                                            <Button
                                                onClick={() => {
                                                    store.setRight(false)
                                                }}
                                                icon={<IconDelete />}
                                            />
                                        </Space>
                                    }
                                    >
                                        <TabPane key='1' title='预览'>
                                        </TabPane>
                                    </Tabs>
                                    <div className={styles.pageRight}>
                                        <MyErrorBoundary>
                                            <PageElement />
                                        </MyErrorBoundary>
                                    </div>
                                </div>
                            )
                                : ''
                        }
                    />
                ) : (
                    <Tabs type='card-gutter'
                        activeTab={activeTab}
                        className={styles['tabs']}
                        editable
                        showAddButton={false}
                        onChange={setActiveTab}
                        onDeleteTab={(key) => {
                            delete store.pageStore[key];
                            store.setTabList(list.filter((o) => {
                                return o.key !== key;
                            }))
                            if(key === activeTab){
                                setActiveTab(id);
                            }
                        }}
                        extra={
                            <Space>
                                <Button
                                    key="1" size='small'
                                    type='secondary'
                                    onClick={() => {
                                        history.goBack();
                                    }}
                                >
                                    返回
                                </Button>
                                <AsyncButton key="2" size="small" type="primary"
                                    onClick={() => {
                                        // console.log('saveData', pageStore.getData())
                                        return store.saveData();
                                    }}
                                >
                                    保存
                                </AsyncButton>
                                <Button
                                    key="3" size="small"
                                    type="primary"
                                    onClick={() => {
                                        store.openCodeEditor();
                                    }}
                                >
                                    VsCode
                                </Button>
                            </Space>
                        }
                    >
                        {loading && <Spin />}
                        {list.map((o) => {
                            return (
                                <TabPane
                                    destroyOnHide
                                    closable={Boolean(o.isComponent)}
                                    {...o}
                                    title={
                                        <span>
                                            {
                                                o.isComponent ? <IconCommon style={{ marginRight: 6 }} /> : <IconCalendar style={{ marginRight: 6 }} />
                                            }
                                            {o.title}
                                        </span>
                                    }
                                >
                                    <CustomPage
                                        store={store.pageStore[o.key]}
                                        openModuleEidt={(key) => store.openModuleEidt(key)}
                                    />
                                </TabPane>
                            )
                        })}
                    </Tabs>
                )
                }
                <Modal
                    title={
                        <div style={{ textAlign: 'left', display: 'flex', alignItems: 'center' }}>
                            预览
                            <IconToRight onClick={() => {
                                store.setPVisible(false)
                                store.setRight(true)
                            }} style={{ fontSize: '24px', marginLeft: '8px' }} />
                        </div>
                    }
                    visible={store.pVisible}
                    className={`${styles.modal} ${styles.fullscreen} arco-modal-page-html`}
                    footer={null}
                    maskClosable={false}
                    onCancel={() => {
                        store.setPVisible(false);
                    }}
                >
                    <MyErrorBoundary>
                        <PageElement />
                    </MyErrorBoundary>
                </Modal>
            </div >
        )
    })
}